keyframes_css:
@keyframes spark-fly {
  0% {
    opacity: 1;
    transform: translate(0, 0) scale(1);
  }
  100% {
    opacity: 0;
    transform: translate(var(--tx), var(--ty)) scale(0);
  }
}

@keyframes bolt-flash {
  0%, 100% {
    opacity: 0;
    filter: drop-shadow(0 0 0px #fff);
  }
  50% {
    opacity: 1;
    filter: drop-shadow(0 0 8px #ffff00) drop-shadow(0 0 4px #0ff);
  }
}

@keyframes sphere-charge {
  0%, 100% {
    box-shadow: inset 0 0 10px rgba(0, 255, 255, 0.3);
  }
  50% {
    box-shadow: inset 0 0 20px rgba(0, 255, 255, 0.8), 0 0 15px rgba(255, 255, 0, 0.6);
  }
}

.demo-stage {
  position: relative;
  width: 200px;
  height: 200px;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  border-radius: 8px;
  overflow: hidden;
}

.demo-stage::before {
  content: '';
  position: absolute;
  width: 40px;
  height: 40px;
  background: radial-gradient(circle at 30% 30%, #00ffff, #0088ff);
  border-radius: 50%;
  top: 50%;
  left: 25%;
  transform: translate(-50%, -50%);
  animation: sphere-charge 1.5s ease-in-out infinite;
}

.demo-stage::after {
  content: '';
  position: absolute;
  width: 40px;
  height: 40px;
  background: radial-gradient(circle at 30% 30%, #ffff00, #ff8800);
  border-radius: 50%;
  top: 50%;
  right: 25%;
  transform: translate(50%, -50%);
  animation: sphere-charge 1.5s ease-in-out infinite;
}

.bolt {
  position: absolute;
  width: 2px;
  height: 60px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: linear-gradient(to bottom, transparent, #ffff00, transparent);
  animation: bolt-flash 1.5s ease-in-out infinite;
}

.spark {
  position: absolute;
  width: 4px;
  height: 4px;
  background: #ffff00;
  border-radius: 50%;
  top: 50%;
  left: 50%;
  pointer-events: none;
}

.spark:nth-child(2) {
  --tx: 45px;
  --ty: -30px;
  animation: spark-fly 1.2s ease-out infinite;
  animation-delay: 0.3s;
}

.spark:nth-child(3) {
  --tx: -40px;
  --ty: -35px;
  animation: spark-fly 1.2s ease-out infinite;
  animation-delay: 0.4s;
}

.spark:nth-child(4) {
  --tx: 30px;
  --ty: 40px;
  animation: spark-fly 1.2s ease-out infinite;
  animation-delay: 0.5s;
}

.spark:nth-child(5) {
  --tx: -45px;
  --ty: 35px;
  animation: spark-fly 1.2s ease-out infinite;
  animation-delay: 0.6s;
}

@keyframes spread {
  0% {
    width: 10px;
    height: 10px;
    opacity: 1;
  }
  100% {
    width: 180px;
    height: 180px;
    opacity: 0;
  }
}

@keyframes drop {
  0% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

.demo-stage {
  width: 200px;
  height: 200px;
  background: #f5f5f5;
  position: relative;
  overflow: hidden;
  border: 2px solid #333;
}

.demo-stage::before {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle, #1a1a1a 0%, #3d3d3d 70%);
  border-radius: 50%;
  animation: spread 3s ease-out infinite;
}

.demo-stage::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 8px;
  height: 8px;
  background: #0d0d0d;
  border-radius: 50%;
  transform: translate(-50%, -50%);
  animation: drop 3s ease-out infinite;
}

@keyframes elevator-move {
  0% {
    transform: translateY(0);
  }
  25% {
    transform: translateY(-60px);
  }
  50% {
    transform: translateY(-60px);
  }
  75% {
    transform: translateY(0);
  }
  100% {
    transform: translateY(0);
  }
}

@keyframes door-open {
  0%, 20% {
    width: 100%;
  }
  30%, 70% {
    width: 0%;
  }
  80%, 100% {
    width: 100%;
  }
}

@keyframes floor-indicator {
  0%, 25% {
    opacity: 0.3;
  }
  26%, 50% {
    opacity: 1;
  }
  51%, 75% {
    opacity: 0.3;
  }
  76%, 100% {
    opacity: 1;
  }
}

.demo-stage {
  width: 200px;
  height: 200px;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 10px;
  overflow: hidden;
  position: relative;
}

.demo-stage .elevator-shaft {
  width: 80px;
  height: 150px;
  background: #222;
  border: 3px solid #666;
  border-radius: 5px;
  position: relative;
  overflow: hidden;
}

.demo-stage .elevator-car {
  width: 100%;
  height: 40px;
  background: linear-gradient(to bottom, #e74c3c, #c0392b);
  position: absolute;
  top: 0;
  animation: elevator-move 4s infinite;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 2px solid #a93226;
}

.demo-stage .door-left,
.demo-stage .door-right {
  position: absolute;
  top: 0;
  width: 50%;
  height: 100%;
  background: #34495e;
  border: 1px solid #2c3e50;
}

.demo-stage .door-left {
  left: 0;
  animation: door-open 4s infinite;
  transform-origin: right;
}

.demo-stage .door-right {
  right: 0;
  animation: door-open 4s infinite reverse;
  transform-origin: left;
}

.demo-stage .floor-light {
  width: 8px;
  height: 8px;
  background: #f39c12;
  border-radius: 50%;
  position: absolute;
  bottom: 8px;
  animation: floor-indicator 4s infinite;
}

.demo-stage .floor-light:nth-child(3) {
  right: 8px;
}

.demo-stage .floor-number {
  font-size: 12px;
  color: white;
  font-weight: bold;
  animation: floor-indicator 4s infinite;
}

@keyframes firefly-glow {
